+static bool
+match_ipv6_range(const ipv6_range_t *range, const ws_in6_addr *addr)
+{
+    int i;
+
+    for (i = 0; i < 16; i++) {
+        if (range->addr[i] != (addr->bytes[i] & range->mask[i])) {
+            return false;
+        }
+    }
+    return true;
+}
